import random

from txn_simulator import Workload
from workloads import WORKLOAD_1, WORKLOAD_2, WORKLOAD_3

# EVOLVE-BLOCK-START

import time

def _extract_txn_ops(workload, n):
    """Best-effort extraction of per-transaction operation lists from the
    workload object, to build the read/write conflict graph."""
    for attr in ("txns", "transactions", "txn_ops", "ops", "operations",
                 "txn_list", "workload", "seqs"):
        obj = getattr(workload, attr, None)
        if obj is None:
            continue
        try:
            items = list(obj)
        except TypeError:
            continue
        if len(items) == n:
            # items may be strings like "w-17 r-5 ..." or dicts/lists.
            return items
    return None


def _conflict_preds(txn_ops, n):
    """Return preds[i] = set of j whose conflict must precede i is NOT
    encoded directionally here; we return an undirected conflict neighbor
    set per transaction plus a write-key map used by the layering."""
    # Parse operations.
    txn_items = []  # list of (set_of_read_keys, set_of_write_keys)
    for ops in txn_ops:
        reads, writes = set(), set()
        if isinstance(ops, str):
            for tok in ops.split():
                parts = tok.split("-", 1)
                if len(parts) == 2:
                    if parts[0] == "r":
                        reads.add(parts[1])
                    elif parts[0] == "w":
                        writes.add(parts[1])
        elif isinstance(ops, dict):
            for k, v in ops.items():
                if k == "r" or k == "reads":
                    reads.update(str(x) for x in (v if isinstance(v, (list, set, tuple)) else [v]))
                elif k == "w" or k == "writes":
                    writes.update(str(x) for x in (v if isinstance(v, (list, set, tuple)) else [v]))
        elif isinstance(ops, (list, tuple)):
            for tok in ops:
                s = str(tok)
                parts = s.split("-", 1)
                if len(parts) == 2:
                    if parts[0] == "r":
                        reads.add(parts[1])
                    elif parts[0] == "w":
                        writes.add(parts[1])
        txn_items.append((reads, writes))

    # Conflict: share a key with at least one write involved (rw or ww).
    key_txns = {}
    for i, (reads, writes) in enumerate(txn_items):
        for k in writes:
            key_txns.setdefault(("w", k), set()).add(i)
        for k in reads:
            key_txns.setdefault(("r", k), set()).add(i)

    neighbors = [set() for _ in range(n)]
    for (tag, k), txns in key_txns.items():
        tl = sorted(txns)
        for a in range(len(tl)):
            for b in range(a + 1, len(tl)):
                i, j = tl[a], tl[b]
                # rw conflict only if the writer writes and reader reads;
                # a (r,r) group never conflicts, guaranteed by tag split.
                neighbors[i].add(j)
                neighbors[j].add(i)
    return neighbors


def get_best_schedule(workload, num_seqs):
    """
    Approach: dependency-layered construction over the read/write conflict
    graph, with randomized restarts and swap-based local search.

    Mechanism: build the write-conflict graph (edge if two transactions
    touch a common key and at least one access is a write). Repeatedly
    form layers: a transaction joins the current layer once all of its
    already-placed conflicts have been placed; when no conflict-free
    candidate exists (cycle), break it by picking the pending transaction
    with the fewest unplaced conflicts. Any within-layer order preserves
    conflict freedom, so randomized restarts over layer orderings explore
    a structural subspace the sequential greedy cannot. Each candidate is
    evaluated with the simulator's true cost; the best sequence is then
    refined with or-opt reinsertion + adjacent swaps (first improvement)
    until the per-workload deadline. Identity permutation kept as a
    validity fallback. Budget: ~90s per workload (270s total, inside the
    360s limit).
    """
    n = workload.num_txns
    t0 = time.time()
    deadline = t0 + 90.0

    cache = {}

    def seq_cost(seq):
        key = tuple(seq)
        c = cache.get(key)
        if c is None:
            c = workload.get_opt_seq_cost(seq)
            cache[key] = c
        return c

    best_seq = list(range(n))
    best_cost = seq_cost(best_seq)

    txn_ops = _extract_txn_ops(workload, n)
    layers = None
    if txn_ops is not None:
        try:
            neighbors = _conflict_preds(txn_ops, n)
            # Layered topological construction with randomized tie-breaks.
            layers = []
            placed = [False] * n
            remaining = set(range(n))
            while remaining:
                layer = [t for t in remaining
                         if all(placed[u] or u == t for u in neighbors[t])]
                if not layer:
                    # Cycle break: fewest unplaced conflicts first.
                    layer = [min(remaining,
                                 key=lambda t: sum(1 for u in neighbors[t] if not placed[u]))]
                layers.append(layer)
                for t in layer:
                    placed[t] = True
                    remaining.discard(t)
        except Exception:
            layers = None

    if layers is not None:
        # Randomized restarts: shuffle within-layer order, evaluate true cost.
        while time.time() < deadline:
            flat = []
            for layer in layers:
                l2 = list(layer)
                random.shuffle(l2)
                flat.extend(l2)
            c = seq_cost(flat)
            if c < best_cost:
                best_cost, best_seq = c, list(flat)
            # Occasionally randomize the layer construction itself by
            # greedily perturbing which transaction breaks a cycle.
            if random.random() < 0.3:
                # Random rotation of one layer's contents with a neighbor
                # layer to diversify the topological structure explored.
                if len(layers) > 1:
                    li = random.randrange(len(layers) - 1)
                    a, b = layers[li], layers[li + 1]
                    if a and b:
                        t = a.pop(random.randrange(len(a)))
                        b.insert(random.randrange(len(b) + 1), t)

        # --- Local search on the best layer schedule ---
        def one_pass(seq, cost):
            # Or-opt reinsertion.
            for i in range(n):
                if time.time() > deadline:
                    return seq, cost, False
                item = seq[i]
                rest = seq[:i] + seq[i + 1:]
                for j in range(n):
                    if j == i:
                        continue
                    cand = rest[:j] + [item] + rest[j:]
                    c = seq_cost(cand)
                    if c < cost:
                        return cand, c, True
            # Adjacent swaps.
            for i in range(n - 1):
                if time.time() > deadline:
                    return seq, cost, False
                cand = list(seq)
                cand[i], cand[i + 1] = cand[i + 1], cand[i]
                c = seq_cost(cand)
                if c < cost:
                    return cand, c, True
            return seq, cost, False

        while time.time() < deadline:
            seq, cost, imp = one_pass(best_seq, best_cost)
            if not imp:
                break
            if cost < best_cost:
                best_cost, best_seq = cost, list(seq)

    assert len(set(best_seq)) == n
    return best_cost, best_seq

